    public static int enSame(int emonT, emon.Port.Cells a, emon.Port.Cells b, String law) {
        emon.Testport.assertEq(emon.Port.cellsLen(a), emon.Port.cellsLen(b), law);
        int i = 0;
        while (i < emon.Port.cellsLen(a)) {
            emon.Testport.assertEq(emon.Port.cellsAt(a, i), emon.Port.cellsAt(b, i), law);
            i += 1;
        }
        return 0;
    }
    public static void testTheOrderOfAResolutionDoesNotDependOnTheOrderOrRepeatsOfItsInputs() {
        emon.Port.Cells l1 = emon.Port.newCells();
        emon.Port.Cells l2 = emon.Port.newCells();
        emon.Port.Cells e1 = emon.Port.newCells();
        emon.Port.Cells e2 = emon.Port.newCells();
        emon.Port.Cells i1 = emon.Port.newCells();
        emon.Port.Cells i2 = emon.Port.newCells();
        emon.Port.Cells a = emon.Port.newCells();
        emon.Port.Cells b = emon.Port.newCells();
        emon.Port.cellsPush(l1, 1936744704);
        emon.Port.cellsPush(l1, Engines.pkLangEng());
        emon.Port.cellsPush(l1, 1718771968);
        emon.Port.cellsPush(l2, 1718771968);
        emon.Port.cellsPush(l2, 1936744704);
        emon.Port.cellsPush(l2, Engines.pkLangEng());
        emon.Port.cellsPush(l2, Engines.pkLangEng());
        emon.Port.cellsPush(e1, Engines.engPpocr());
        emon.Port.cellsPush(e1, Engines.engTesseract());
        emon.Port.cellsPush(e2, Engines.engTesseract());
        emon.Port.cellsPush(e2, Engines.engPpocr());
        emon.Port.cellsPush(e2, Engines.engTesseract());
        emon.Port.cellsPush(i1, Packdata.pkidTessFastSpa());
        emon.Port.cellsPush(i1, Packdata.pkidPp5DetMobile());
        emon.Port.cellsPush(i2, Packdata.pkidPp5DetMobile());
        emon.Port.cellsPush(i2, Packdata.pkidTessFastSpa());
        emon.Port.cellsPush(i2, Packdata.pkidPp5DetMobile());
        emon.Testport.assertEq(enResolve(Engines.pclsLinux(), Engines.pkfOsd(), l1, e1, i1, a), Engines.pkerrOk(), "one order");
        emon.Testport.assertEq(enResolve(Engines.pclsLinux(), Engines.pkfOsd(), l2, e2, i2, b), Engines.pkerrOk(), "another");
        enSame(0, a, b, "the same rows in the same order");
        emon.Testport.assertThat(Engines.pkRows(a) > 6, "English, Spanish, French, OSD and three models, and PP-OCR's two unreadable languages");
    }
