    public static void testResolutionRefusesWhatTheCatalogueAndTheTableDoNotHave() {
        emon.Port.Cells langs = emon.Port.newCells();
        emon.Port.Cells engs = emon.Port.newCells();
        emon.Port.Cells installed = emon.Port.newCells();
        emon.Port.Cells out = emon.Port.newCells();
        StringBuilder msg = emon.Testport.newText();
        enCells1(engs, 99);
        emon.Testport.assertEq(enResolve(Engines.pclsMacos(), 0, langs, engs, installed, out), Engines.pkerrUnknownEngine(), "an engine that is not in the table");
        emon.Testport.assertEq(emon.Port.cellsAt(out, 0), 99, "the subject");
        Engines.pkExplain(Engines.pkerrUnknownEngine(), out, msg);
        emon.Testport.assertText(msg, "unknown engine: 99", "named");
        enCells1(engs, Engines.engPdfium());
        emon.Testport.assertEq(enResolve(Engines.pclsMacos(), 0, langs, engs, installed, out), Engines.pkerrNotOcr(), "a renderer does not read");
        enCells1(engs, Engines.engAppleVision());
        emon.Testport.assertEq(enResolve(Engines.pclsWindows(), 0, langs, engs, installed, out), Engines.pkerrEngineClass(), "Vision is not on Windows");
        StringBuilder m2 = emon.Testport.newText();
        Engines.pkExplain(Engines.pkerrEngineClass(), out, m2);
        emon.Testport.assertText(m2, "engine is not available on the platform class: \"apple-vision\" on \"windows\"", "both named");
        emon.Port.cellsDrop(engs, 0);
        emon.Testport.assertEq(enResolve(9, 0, langs, engs, installed, out), Engines.pkerrUnknownClass(), "a class that is not one");
        emon.Testport.assertEq(emon.Port.cellsAt(out, 0), 9, "the subject");
        enCells1(installed, 99);
        emon.Testport.assertEq(enResolve(Engines.pclsMacos(), 0, langs, engs, installed, out), Engines.pkerrUnknownPack(), "an installed pack that is not in the catalogue");
        emon.Testport.assertEq(emon.Port.cellsAt(out, 0), 99, "the subject");
        emon.Port.cellsDrop(installed, 0);
        enCells1(langs, 0);
        emon.Testport.assertEq(enResolve(Engines.pclsMacos(), 0, langs, engs, installed, out), Engines.pkerrBadLanguage(), "no language is 0");
    }
