    public static void testTheRecordOfAnEngineTableFollowsTheTableAndRefusesWhatItDoesNotHave() {
        emon.Port.Cells avail = emon.Port.newCells();
        emon.Port.Cells out = emon.Port.newCells();
        emon.Port.cellsPush(avail, Engines.engPpocr());
        emon.Port.cellsPush(avail, Engines.engTesseract());
        emon.Port.cellsPush(avail, Engines.engPpocr());
        emon.Testport.assertEq(Engines.pkRecordEngines(out, Engines.pclsMacos(), avail), Engines.pkerrOk(), "the engines of a hybrid run");
        emon.Testport.assertEq(emon.Port.cellsLen(out), 6, "two rows");
        emon.Testport.assertEq(emon.Port.cellsAt(out, 0), Engines.engTesseract(), "in the table's order, once each");
        emon.Testport.assertEq(emon.Port.cellsAt(out, 1), Engines.pkEngineCaps(Engines.engTesseract()), "the caps the table declares");
        emon.Testport.assertEq(emon.Port.cellsAt(out, 2), Engines.eroleIncumbent(), "the role it takes by default");
        emon.Testport.assertEq(emon.Port.cellsAt(out, 3), Engines.engPpocr(), "second");
        emon.Testport.assertEq(emon.Port.cellsAt(out, 5), Engines.eroleChallenger(), "the challenger");
        enCells1(avail, Engines.engAppleVision());
        emon.Testport.assertEq(Engines.pkRecordEngines(out, Engines.pclsWindows(), avail), Engines.pkerrEngineClass(), "an engine that cannot run on the class is not recorded");
        enCells1(avail, 42);
        emon.Testport.assertEq(Engines.pkRecordEngines(out, Engines.pclsMacos(), avail), Engines.pkerrUnknownEngine(), "nor one that is not in the table");
        emon.Testport.assertEq(emon.Port.cellsAt(out, 0), 42, "named");
        emon.Port.cellsDrop(avail, 0);
        emon.Testport.assertEq(Engines.pkRecordEngines(out, Engines.pclsMacos(), avail), Engines.pkerrOk(), "no engine at all");
        emon.Testport.assertEq(emon.Port.cellsLen(out), 0, "no rows");
        emon.Testport.assertEq(Engines.pkRecordEngines(out, 0, avail), Engines.pkerrUnknownClass(), "no class");
    }
    public static int enProd(emon.Transcriptctx.Tr t) {
        emon.Port.Cells k = emon.Port.newCells();
        emon.Port.Cells v = emon.Port.newCells();
        emon.Port.cellsPush(k, 101);
        emon.Port.cellsPush(k, 110);
        emon.Port.cellsPush(k, 103);
        emon.Port.cellsPush(v, 116);
        emon.Port.cellsPush(v, 101);
        emon.Port.cellsPush(v, 115);
        emon.Port.cellsPush(v, 115);
        return Transcript.trAddProducer(t, k, v);
    }
    public static int enReadTable(int emonT) {
        byte[] b = emon.Testport.textBlob("{:emon-transcript 1\n :pk-engines [{:engine \"tesseract\" :caps 7339791 :role :incumbent} {:engine \"apple-vision\" :caps 1048992 :role :reader}]\n :producer {:eng \"tess\"}\n :inputs [{:index 0 :length 94562}]\n :entries []}\n");
        emon.Transcriptctx.Tr t = new emon.Transcriptctx.Tr();
        StringBuilder out = emon.Testport.newText();
        emon.Testport.assertEq(Transcript.trRead(t, b), 0, "a transcript with an engine table reads");
        emon.Testport.assertEq(Transcript.trNEngines(t), 2, "two engines");
        emon.Testport.assertEq(Transcript.trEngEngine(t, 0), Engines.engTesseract(), "the first");
        emon.Testport.assertEq(Transcript.trEngCaps(t, 0), 7339791, "its caps");
        emon.Testport.assertEq(Transcript.trEngRole(t, 0), Engines.eroleIncumbent(), "its role");
        emon.Testport.assertEq(Transcript.trEngEngine(t, 1), Engines.engAppleVision(), "the second");
        emon.Testport.assertEq(Transcript.trEngCaps(t, 1), 1048992, "its caps");
        emon.Testport.assertEq(Transcript.trEngRole(t, 1), Engines.eroleReader(), "an uncalibrated engine read alone");
        Transcript.trWrite(t, out);
        emon.Testport.assertText(out, "{:emon-transcript 1\n :pk-engines [{:engine \"tesseract\" :caps 7339791 :role :incumbent} {:engine \"apple-vision\" :caps 1048992 :role :reader}]\n :producer {:eng \"tess\"}\n :inputs [{:index 0 :length 94562}]\n :entries []}\n", "read and written again, the same bytes");
        return 0;
    }
