    public static void testTheEngineTableIsWrittenFirstAndReadBack() {
        emon.Transcriptctx.Tr t = new emon.Transcriptctx.Tr();
        StringBuilder out = emon.Testport.newText();
        Transcript.trAddEngine(t, Engines.engTesseract(), 7339791, Engines.eroleIncumbent());
        Transcript.trAddEngine(t, Engines.engPpocr(), 24928, Engines.eroleChallenger());
        enProd(t);
        Transcript.trAddInput(t, 0, 94562);
        Transcript.trWrite(t, out);
        emon.Testport.assertText(out, "{:emon-transcript 1\n :pk-engines [{:engine \"tesseract\" :caps 7339791 :role :incumbent} {:engine \"ppocr\" :caps 24928 :role :challenger}]\n :producer {:eng \"tess\"}\n :inputs [{:index 0 :length 94562}]\n :entries []}\n", "the table comes before the producer, the inputs and the entries");
        enReadTable(0);
        enReadNone(0);
    }
